describe('Bottom Sheet Functionality', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.viewport('iphone-6'); // Simulate mobile viewport
    });

    it('should display the bottom sheet when the button is clicked', () => {
        cy.get('[data-testid="open-bottom-sheet"]').click(); // Replace with the actual selector
        cy.get('[data-testid="bottom-sheet"]').should('be.visible'); // Check if bottom sheet is visible
    });

    it('should close the bottom sheet when the close button is clicked', () => {
        cy.get('[data-testid="open-bottom-sheet"]').click(); // Open the bottom sheet
        cy.get('[data-testid="close-bottom-sheet"]').click(); // Replace with the actual selector
        cy.get('[data-testid="bottom-sheet"]').should('not.be.visible'); // Check if bottom sheet is closed
    });
});
